ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_3"] = {
{"r7_school_garage_roll_call","scanner",1,2,6,9,1,{"Base","Base to all buses, roll call before anybody pulls out - I want to know who I've got - bus 3","Bus 12","Base, Bus 12 for Bus 3 - Wanda's not coming, her boy's sick","Base","Copy - bus 7","Bus 7","Bus 7, here, and my air brakes are groaning something awful","Base","Take 9 instead, the keys are on the board - bus 14","Base","Bus 14, bus 14, Base","Base","All right, that's four drivers out of eleven, everybody keep your radio on, keep your doors shut at the stops, and don't get out of the bus for anybody","Bus 12","Base, what if somebody's flagging us down on the road?","Base","Open the door and let them on, I said don't get out, I didn't say don't let anybody in"}},
{"exp_school_secretary","caller_story_sad",2,14,0,23,1,{"Vera","Parents used to call the school to ask if it was closing for snow","June","Even when there wasn't any snow?","Vera","Especially then, they wanted somebody to decide the morning for them","June","Were you the secretary?","Vera","Twenty-six years, I could recognize half the voices before they gave a name","Vera","Now I keep picking up dead telephones","June","Would you rather we talked about something else?","Vera","No, it's nice answering a question again"}},
{"more_radio_tired_counting","host",2,3650,22,4,1,{"June","I counted the pencils on this desk three times","Lou","Lose one?","June","No, got three different answers","Lou","How many pencils?","June","Four - no-- wait, I counted the pen again","Lou","Might be time for someone else to sit in the chair","June","Oh, don't start, I'm finishing this and then I'm going","Lou","I'll count them for you","June","There are either four, five or seven","Lou","June - go lie down"}},
{"more_radio_motel_knock","caller_story_horror",2,14,21,5,1,{"Wade","Somebody knocked on the wall next to us","Wade","Not a door, the wall between the rooms","Wade","My wife tapped back before I could stop her","Wade","Then nothing for the rest of the night","June","Did you find out who it was?","Wade","No, we left when we could","Wade","I nearly went round, had my shoes on, hand on the door","June","But you didn't","Wade","My wife said, 'Wade - get away from that fucking door.' Never swears, my wife","Wade","So I did, packed our stuff instead - still don't know who was next door"}},
{"more_radio_melon_dispute","caller_joke",2,3650,0,23,1,{"June","Frank says he has a question about manners","Frank","If a man gives you a watermelon, does he own the seeds?","June","That depends how strange the man is","Frank","My brother-in-law","June","Oh, I can't help you with a brother-in-law, Frank","Frank","He says they're his grandfather's seeds","June","Did you promise to give them back?","Frank","I promised not to spit them on his porch","June","Well, you didn't promise him the seeds","Frank","THANK you - say it again, he's right here pretending he can't hear"}},
{"more_radio_firehall_recipe","caller_joke",2,3650,0,23,1,{"Benny","Somebody wants our fire hall's chili recipe","June","Is it a secret?","Benny","Nobody knows it, everybody added something","June","Was it any good?","Benny","Depends which end of the pot you got","June","Nobody stirred it?","Benny","Chief said stirring was how you ruined the layers","June","Layers of chili?","Benny","We didn't question him, he knew where the antacids were","Benny","Actually, don't give that out as a recipe, we don't need complaints"}},
{"more_radio_cashier_receipt","caller_story_sad",2,3650,0,23,1,{"Donna","I asked somebody if they wanted a receipt today","June","At a shop?","Donna","No, handed them a cup of water","Donna","'Would you like your receipt?' Just came out, I could've died","Donna","He said yes, just to be nice, I think","June","Did you make one?","Donna","Wrote 'water' on a scrap - put thank you underneath","June","Did he keep it?","Donna","Folded it and put it in his wallet","Donna","I nearly told him to have a nice day as well - caught that one, at least"}},
{"king_radio_still_listening","host",2,3650,0,23,1,{"June","If you're still listening, you don't have to have something useful to say","June","I know we've spent a lot of time asking for names and places","June","Sometimes you just want somebody to pick up","June","I used to let the telephone ring when I was tired","June","Thought whoever it was would try again","June","That's a stupid thing to keep thinking about, isn't it","June","Anyway. You can say hello","June","I'll count that as a reason to keep talking"}},
{"king_radio_no_shortcuts","instruction",2,3650,0,23,1,{"June","Please don't take a caller's route as a promise","June","Somebody getting through yesterday doesn't tell us what is there now","June","I know it's hard to hear that after you've packed","June","I'd rather disappoint you here than send you into something","June","Ask when a report was made","June","Ask whether they saw it themselves","June","And if they don't know, let them say they don't know","June","We can work with an honest gap. We can't work with a promise somebody invented"}},
{"king_radio_ordinary_voice","caller_story_sad",2,3650,0,23,1,{"Iris","You sound like someone I knew","June","Someone you liked?","Iris","Most days","June","I'll try to earn one of those days","Iris","Could you just say my name?","June","Iris","Iris","Yeah. Thank you","June","You're welcome, Iris"}},
{"king_radio_small_boundary","instruction",2,3650,0,23,1,{"June","If somebody offers you a place to stay, ask what they're offering","June","A night isn't forever. Company isn't a debt","June","You can be grateful and still ask a question","June","Where can I put my things? When do you need me to leave?","June","And the person asking to stay can hear no","June","I know kindness feels scarce","June","That doesn't mean you have to say yes to everything","June","Try to be clear with each other"}},
{"king_radio_one_more_minute","sign_off",2,3650,0,23,1,{"June","I need to leave the microphone for a little while","June","I don't have an exact time for you","June","Before I go, thank you to everyone who listened","June","Especially the ones who didn't know what to say","June","You were part of this too","June","If somebody is sitting with you, maybe say hello to them","June","You don't need a speech","June","Neither do I. Take care of each other"}},
{"king_radio_carpenter_pencil","caller_joke",2,3650,0,23,1,{"Dale","Spent twenty minutes looking for the pencil behind my ear","June","First time?","Dale","No. Usually somebody has the decency to laugh at me","June","Want me to?","Dale","Wouldn't mind","June","Dale, you're an idiot","Dale","There we are. Sounds like work again","June","Don't lose the other ear"}},
{"king_radio_requested_song","host",2,3650,0,23,1,{"June","Somebody asked for a song and gave me half of one lyric","June","I won't pretend I know which one you meant","June","The note says your sister used to sing it in the car","June","That's a better clue, just not one I can use","June","If you remember the title, you can try again","June","I can't promise I have it","June","But you can tell me about your sister","June","I don't need to recognize the song for that"}},
{"knox_shift_end","scanner",2,7,0,23,1,{"Unit Six","Dispatch, who is relieving me?","Dispatch","I don't have a replacement showing, Six","Unit Six","My shift ended hours ago, my wife's not answering","Dispatch","I know - give me a moment with the line clear"}},
{"r1_d2_quarantine_order_read","scanner",2,2,6,10,3,{"Post 4","Post 4 to all units, all agencies on this channel - stand by for an order from the Governor's office, through the Commissioner","Post 4","Effective 0600 hours, Knox County is under a quarantine order - no vehicle or pedestrian traffic is to leave the county","Post 4","The Department of the Army is assuming control of the river crossings, US-31W at the county line, and all routes south and east","Post 4","State Police will assist the Army at their direction, local agencies are to keep citizens in their homes","Knox 1","Knox 1 to Post 4, this is Sheriff Groves - for how long?","Post 4","Sheriff, the order doesn't say","Knox 1","Does it say what I'm supposed to tell the people in this county who packed their cars last night?","Post 4","It says stay in your homes, Sheriff","Knox 1","Copy - Knox 1 to all Knox units, you heard it - be gentle with folks, most of them have never had a soldier point anything at them"}},
{"r1_d2_army_liaison_by_1400","scanner",2,2,8,13,1,{"Army Liaison","Knox County Sheriff's Office, this is the Army liaison at the Muldraugh command post, on your channel","Dispatch","Go ahead, Army","Army Liaison","Request you clear all county units and civilian vehicles from US-31W north of the Muldraugh bypass by 1400 hours","Knox 11","Knox 11 - what happens at 1400?","Army Liaison","Clear the road by 1400, deputy","Knox 11","There's people in cars stuck on that road without enough gas to go anywhere","Army Liaison","Then they walk, deputy - south, away from the line","Knox 20","Knox 20, we copy, we'll move who we can - Army, put it in your log that the county asked for more time","Army Liaison","It's logged"}},
{"r1_d2_funeral_escort_1638","scanner",2,2,9,17,2,{"Knox 11","Knox 11 to Knox County, I've got a family at the Pentecost farm on 1638 asking for an escort to their family cemetery","Dispatch","An escort? Today?","Knox 11","Their grandmother passed in her sleep last night - ninety-one, no bites, nothing like that, they want her buried before dark","Dispatch","The coroner can't come, Knox 11","Knox 11","They know, the son's a doctor, he signed what he could - dispatch, Mrs. Pentecost taught fourth grade for forty years, she taught me","Dispatch","Then escort her - show you out with a funeral procession","Knox 11","Procession's moving on 1638, four cars and a pickup with the casket - lights on, twenty miles an hour","Knox 11","Dispatch, the cars coming the other way are pulling onto the shoulder - a man just got out of his truck and took his hat off","Dispatch","Even today","Knox 11","Even today - Knox 11, we're at the cemetery, I'll stand at the gate with the shotgun while they say their piece"}},
{"r1_d2_air1_second_base","scanner",2,2,8,18,1,{"Air-1","Air-1 to Louisville Radio, I'm at bingo fuel, requesting a place to put down, there's a crowd on the ramp at Bowman Field","Louisville Radio","Air-1, stand by","Air-1","Radio, there's not a lot of standing by left in this tank","Louisville Radio","Air-1, Second District says the ball field at the high school on Dixie is clear, fenced, gate locked","Air-1","Copy, heading there - can I get a car for me and my observer?","Louisville Radio","Nearest car is fifteen minutes out","Air-1","We'll be the two fellas on the pitcher's mound, air-1 is landing","Air-1","Air-1 on the ground, engine off, radio, the aircraft stays here - put it in the log, I parked it on second base"}},
{"r1_d2_marty_shelter_stove","scanner",2,2,10,20,1,{"Marty","This came over the sheriff's channel a little after noon - I'd ask you to listen, and then not drive to West Point","Knox 12","Knox 12 to Knox County, I'm at the West Point High School gym - the principal counts three hundred and ten people","Knox 12","Cots ran out at ninety, they're sleeping on the wrestling mats and the bleachers","Dispatch","Copy, Knox 12, the shelter is closed to new arrivals as of now - all units, do not bring anyone else to West Point High","Knox 12","There's a lady here asking if anyone's seen her husband - Delbert Biggs, sixty-eight, wearing a red ball cap","Dispatch","I'll put it in the log","Knox 12","She says tell whoever hears it that he left the stove on - she says he'll know what that means","Marty","I don't know what it means either - Delbert, if you're out there, I believe she'd like you to come home and see about the stove"}},
{"r1_d2_ems1_parakeet_transport","scanner",2,2,7,19,1,{"EMS 1","EMS 1 to all county ambulances, we have nowhere left to take patients, the hospital's closed and Louisville is not answering","EMS 1","As of now, all units return to quarters, no further transports","Medic 2","Medic 2 - EMS 1, we're on scene with an eighty-year-old woman with a broken hip - no bites, she fell in her kitchen","EMS 1","Medic 2, I copy","Medic 2","So what do I do with her?","EMS 1","Splint her, give her something for the pain, put her in her own bed and leave her with family","Medic 2","She hasn't got family, it's her and a parakeet","EMS 1","Then bring her to quarters with you, Medic 2, and the bird, I'll sign for the bird","Medic 2","Medic 2 copies, transporting one patient and one parakeet to Station 21"}},
{"r1_d2_trooper410_birth_certificate","scanner",2,2,10,19,3,{"Trooper 410","Post 4, 410, at the 31W checkpoint","Post 4","Go ahead, 410","Trooper 410","I've got about two hundred people on foot in front of my car - they want through, the Army line is behind me","Trooper 410","The soldiers back there are putting on masks, and their sergeant just told me to get my car off the road","Post 4","410, the Army has command of that checkpoint - follow their direction","Trooper 410","Post, there's a woman in front of me holding up a baby and a birth certificate - like it's a ticket","Post 4","410, follow their direction","Trooper 410","410 is moving his car, I'm not standing between those rifles and that baby, Post - I'm going to go stand next to her","Post 4","410, say again?","Trooper 410","Nothing, Post. 410 is out of the car"}},
{"r1_d2_rosewood_jail_lunch_menu","scanner",2,2,7,15,1,{"Rosewood Jail","Rosewood Jail to Rosewood 5","Rosewood 5","Go ahead, Arliss","Rosewood Jail","I've got eleven in the tank and the county won't take transfers - nobody's fed them since Friday, my relief never came","Rosewood 5","What are you asking me?","Rosewood Jail","I'm asking you to raise the chief and get me an answer - can I cut loose the misdemeanors?","Rosewood 5","The chief hasn't answered his radio since last night","Rosewood Jail","Then I'm asking you","Rosewood 5","Arliss, I can't authorize that","Rosewood Jail","Nobody can, that's my point, I'm opening the tank for the drunks and the unpaid tickets - the two from the prison transfer stay locked down","Rosewood 5","Put it in writing and sign your name to it","Rosewood Jail","Already wrote it, on the back of a lunch menu"}},
{"r1_d2_families_one_hour","scanner",2,2,11,18,2,{"Knox 1","Knox 1 to all Knox units, every deputy gets one hour, starting now, one car at a time","Knox 1","Go get your family and bring them to the courthouse in Rosewood - bring blankets - bring food - bring their medicine","Knox 1","Knox 20 calls the order, if you don't have anybody to get, you cover for the ones who do","Knox 20","Knox 4, you're first","Knox 4","Knox 4 copies, going for Donna and the dog","Knox 11","Knox 11, I haven't got anybody here - my folks retired to Florida, I'll cover the west end","Knox 20","Knox 12, you're next","Knox 12","Knox 12, my wife's already at the courthouse - she beat me there, she brought a casserole","Knox 1","Tell her the sheriff says thank you, tell her the sheriff would like a corner piece"}},
{"r1_d2_lineman_bucket_relieved","scanner",2,2,8,17,1,{"Engine 21","Engine 21, dispatch, we're on scene at the pole on Dogwood Drive - there's a power company lineman up in his bucket","Engine 21","He's been up there since six this morning, the bucket controls on his truck are on the ground, and so are four of them","Dispatch","Is he injured?","Engine 21","He says negative, he's fine, he's got water, and he needs to use the restroom real bad","Truck 23","Truck 23, we can get a ladder up to him from the other side of the yard if Engine 21 makes some noise","Engine 21","Engine 21 copies, hitting the air horn","Truck 23","They're going to the engine - ladder's up, the lineman is coming across","Truck 23","He's on the ground, he shook every hand on this truck and then ran behind the garage","Engine 21","Dispatch, one civilian rescued from a utility pole - show him relieved"}},
{"r1_d2_rollcall_stand_by_one","scanner",2,2,18,23,3,{"Dispatch","All Knox units, Knox County, I'm doing a status check - answer when I call your number","Dispatch","Knox 4","Knox 4","Knox 4, courthouse","Dispatch","Knox 9","Knox 9","Knox 9, in service, West Point","Dispatch","Knox 11","Knox 11","Knox 11, 31W at the bypass","Dispatch","Knox 12","Knox 12","Knox 12, West Point High, at the gym doors","Dispatch","Knox 15","Dispatch","Knox 15, Knox County","Dispatch","Knox 16","Dispatch","Knox 18 - Knox 18, status","Dispatch","Knox 7 remains out of service - Knox 15, Knox 16 and Knox 18, no answer, last known locations are in the log","Dispatch","Sorry- stand by one","Dispatch","Knox County's back, all units, keep your status current - I'd like to hear from every one of you on the hour"}},
{"r1_d2_chief_late_fees","scanner",2,2,11,21,1,{"Car 1","Car 1 to all Muldraugh Fire companies","Car 1","We're down to two engines with crews and one tanker - the hydrants in the south end are dry","Car 1","From here on, if a structure is unoccupied or we can't confirm occupants, we protect the exposures and we let it burn","Engine 21","Engine 21, chief, the video rental place on Main is going now - nobody inside","Car 1","Let it go, 21, wet down the pharmacy next door - we'll be needing that pharmacy","Engine 21","Copy, chief, there's a couple hundred tapes stacked on the sidewalk out front - somebody tried to save the new releases","Car 1","Leave them, nobody's paying late fees this week"}},
{"r1_d2_tyler_in_unit16","scanner",2,2,16,23,3,{"Child","Hello? Is this the police? It's my dad's car","Dispatch","This is the Sheriff's Office - who am I talking to?","Child","Tyler - I'm eight, my dad's the police - his car's in the road with the doors open","Dispatch","Tyler, is your dad there with you?","Child","No. He said stay in the car. Push the button if I got scared. Can you tell him I pushed it?","Dispatch","That's the button, Tyler. You're talking to me now. Can you find a number on the car?","Child","It says sixteen on the back window, backwards, from in here","Dispatch","All Knox units, Knox 16's boy is in his dad's car on Hillcrest Road. Who's close?","Hardin 12","Hardin 12, I'm on Hillcrest. That's the car, and there's a little boy in the front seat","Dispatch","Tyler, a deputy named Russ is coming up to your window - when he says your name, you can unlock the door","Child","Is my dad coming back?","Dispatch","Russ is going to stay right with you, honey, you go with Russ"}},
{"r1_d2_icu_bag_by_hand","scanner",2,2,12,22,1,{"Hospital","Knox County Hospital to any EMS unit on this channel","Hospital","We're evacuating the building, we have four patients on ventilators in the ICU and no ambulances","EMS 1","Hospital, EMS 1 - I'm sorry, I have no units to send - they're at quarters or out of fuel","Hospital","We're bagging them by hand, there's three of us left up here - we can't bag them all the way to Louisville","EMS 1","Is there anyone else in the building?","Hospital","The first floor isn't ours anymore, we blocked the stairwell with beds","EMS 1","Stand by, I'm coming myself in the supervisor's truck, I can take one","Hospital","Take the youngest - Mr. Adams, bed four - nineteen, motorcycle wreck on Wednesday","EMS 1","On my way - keep squeezing that bag"}},
{"r1_d2_louisville_radio_moves","scanner",2,2,14,23,1,{"Louisville Radio","All cars, all districts, this is Louisville Radio, the communications center is relocating","Louisville Radio","In ten minutes this channel will be unmonitored, switch to the mutual aid channel for all traffic","2-Adam-14","2-Adam-14 - radio, where are you relocating to?","Louisville Radio","Adam-14, keep the air clear","2-Adam-14","Radio, I'm asking because there's nobody else for me to call","Louisville Radio","Adam-14, we're moving to the fire training center on the south side - it has a fence, I'll be there if I get there","2-Adam-14","Copy - drive careful","Louisville Radio","Louisville Radio is off the air at {time}"}},
{"r1_d2_robert23_sally_port","scanner",2,2,6,20,1,{"6-Robert-23","6-Robert-23 to any Fourth District car on mutual aid","4-Boy-22","4-Boy-22, go","6-Robert-23","We're two blocks from the Fourth District station - what's the status inside?","4-Boy-22","Twelve officers and some civilians in the roll call room - the lobby's lost, they came through the front glass","6-Robert-23","Copy, we'll come in through the sally port - tell them to open it on my word and not one second before","4-Boy-22","They copy, they're asking how many of you there are","6-Robert-23","Six - tell them six is plenty","6-Robert-23","Open the sally port, open it now","6-Robert-23","We're in, we have them, everybody in the van, officers in the back, civilians on the floor","4-Boy-22","Robert-23, the desk sergeant won't leave, he says somebody has to answer the phones","6-Robert-23","Tell him he's relieved, tell him that's an order from me, and I don't outrank him"}},
{"r1_d2_pharmacist_reads_names","scanner",2,2,9,16,1,{"Knox 9","Knox 9 to Knox County, I'm standing by at the drugstore in West Point with the pharmacist","Knox 9","He's giving out prescriptions from the steps, he's got the refill list and he's reading names off it","Dispatch","How many people have you got?","Knox 9","About sixty in the lot - nobody's pushing, he calls a name, the person comes up, shows him their arms, he hands over the bag","Knox 9","If they're not there, he calls the name twice and then sets the bag aside on a card table","Dispatch","How many bags on the table?","Knox 9","Twenty-some, he says he's leaving them there with the names facing out - in case","Knox 9","He just called his own name off the list, to see if we were paying attention - folks laughed, first time I've heard that since Friday"}},
{"r1_d2_mayday_600_maple","scanner",2,2,10,22,2,{"Engine 21","Mayday, mayday, mayday! Engine 21, firefighter down in the (stepped on)","Knox 11","Knox 11, dispatch, when you get a chance I need a wrecker at 31W and the bypass","Dispatch","Knox 11, hold your traffic! Unit calling mayday, you were stepped on - say again!","Engine 21","Mayday! Engine 21! Firefighter through the floor into the basement, 600 Maple! Lieutenant Oliver is down there!","Dispatch","Engine 21, copy mayday, 600 Maple, firefighter through the floor - all units, emergency traffic only","Car 1","Car 1 en route - engine 21, do you have a line on him?","Engine 21","We can hear him, he's saying he's okay, he's saying there's something else down there with him","Car 1","Get a ladder down that hole now!","Engine 21","Ladder's down, he's coming up - he's up! He's out! Chief, he's out","Car 1","Car 1 to Engine 21, give me a PAR","Engine 21","Engine 21 has PAR, four of four, the lieutenant wants to know who stepped on his mayday","Knox 11","Knox 11, that would be me - I owe him a beer"}},
{"r1_d2_knox9_honey_bun","scanner",2,2,11,15,1,{"Knox 9","Knox 9 to Knox County, show me 10-7 for lunch","Dispatch","Knox 9, you want to go out of service? Now?","Knox 9","Kidding - show me 10-8 - show me 10-8 until further notice","Dispatch","You're 10-8 - what did you have for lunch?","Knox 9","Half a honey bun I found under the seat, this car looks out for me","Dispatch","Save me the other half","Knox 9","Linda, I'm sorry to be the one to tell you - there was never another half"}},
{"r1_d2_riverside1_legal_pad","scanner",2,2,9,19,1,{"Riverside 1","Riverside 1 to Knox County, I'm at the grocery on Riverside Main - about forty people inside taking what they want","Dispatch","Riverside 1, do you need assistance?","Riverside 1","Negative, the owner handed me a legal pad - I'm standing at the door writing down what folks carry out so he can bill them when this is over","Riverside 1","So far that's mostly bread, peanut butter, diapers and bottled water - and one lady with every can of coffee on the shelf","Dispatch","Is the owner alright with that?","Riverside 1","He says she's his sister-in-law and he'll take it up with her at Thanksgiving","Riverside 1","I did stop one man, he was carrying out a nineteen-inch television from the back office","Dispatch","Where's he going to plug it in?","Riverside 1","That's what I asked him, he put it back"}},
{"r1_d2_muldraugh3_partners_mother","scanner",2,2,8,18,1,{"Muldraugh 3","Muldraugh 3 to Knox County - Linda, did anybody ever reach Danny's mother?","Dispatch","Negative, Muldraugh 3, her phone's been busy since yesterday - I think it's off the hook","Muldraugh 3","Then I'm going over there, she lives on Poplar, behind the Legion hall - show me out","Dispatch","Do you want another unit with you?","Muldraugh 3","No, this one's mine","Muldraugh 3","Muldraugh 3, I told her - she already knew, she saw my car pull up alone","Muldraugh 3","She made me sit down and eat a piece of pie - I didn't want it, she watched me eat all of it","Dispatch","Copy, Muldraugh 3 - take a minute before you go back in service","Muldraugh 3","She's wrapping up the rest of the pie for me - I'll be back in service when she lets me go"}},
{"r1_d2_engine21_door_marks","scanner",2,2,7,18,1,{"Car 1","Car 1 to Engine 21, before dark, I want your crew going house to house on Spruce and Maple - knock, don't go in","Engine 21","Engine 21 copies - what are we marking?","Car 1","Orange paint on the front door - big X. Top of the X, today's date, left side, our engine number, right side, anything we saw, bottom, the number of people who answered","Engine 21","Same as the hurricane crews did down in Florida last year","Car 1","Same thing, somebody coming after us ought to know what we found","Engine 21","Engine 21, first house on Spruce - nobody answers, something inside hit the door when we knocked","Car 1","Mark it and move on - write it plain, so a stranger can read it","Engine 21","Second house, old couple at the upstairs window, they say they're staying, and they'd like us to paint a two and wipe our feet next time"}},
{"r2_d2_marty_first_relay","military",2,2,7,13,3,{"Marty","Good morning, my name is Marty Colburn - I own the feed store on the main road in March Ridge - I am not a radio man","Marty","My late brother-in-law set this transmitter up in my back room to read the livestock auction prices - it has never been used for anything like this","Marty","I also own a scanner, since Friday night it's been picking up the Army - I believe you have a right to hear what they're saying about us","Marty","I won't add to it, I'll only let it play - this came over at about seven o'clock this morning","Hatchet-6","Warden Main, Hatchet-6 - TCP 2 reports eleven civilian vehicles turned back since 0500 - no crossings, two Category Threes put down at the barrier, over","Warden Main","Roger, Hatchet-6 - keep the count - Warden Main, out","Marty","Put down, that's the phrase they use - I've only ever heard it said about horses","Marty","I'll quit talking now- lock your doors, though, and nobody official told me to say it, just me"}},
{"r2_d2_minimize_order","military",2,3,0,23,1,{"Warden-6","All Warden stations, this is Warden-6, minimize is in effect on this net, I say again, minimize is in effect","Warden-6","No casualty figures, no category counts and no unit locations in the clear - our traffic is being monitored by civilians, over","Hatchet-6","Hatchet-6, roger minimize - Sir, most of my stations can't go secure - what do we pass instead, over?","Warden-6","Status goes by runner, this net is for emergencies only - everything else waits, over","Crowbar-6","Crowbar-6 - Sir, request you define emergency - by yesterday's standard or today's, over?","Warden-6","Crowbar-6, you'll know one when you see it - keep all transmissions under ten seconds - Warden-6, out","Unknown Station","Warden-6, if a whole checkpoint runs out of water, is that a ten-second emergency, over?","Warden Main","Station calling Warden-6, identify yourself, station calling, identify, over"}},
{"r2_d2_burn_unit_no","military",2,3,0,23,1,{"Lockbox-1-6","Lockbox-6, Lockbox-1-6 at TCP 1, county ambulance at the far barrier asking to cross into Louisville with a child patient, over","Lockbox-6","What's the patient, over?","Lockbox-1-6","Paramedic says a boy, nine, burns from a kitchen fire, no bites - he's shouting it across the barricade, he wants the burn unit in Louisville, over","Lockbox-6","Can your medic confirm no bites, over?","Lockbox-1-6","Negative, my medic isn't allowed past the second barrier, the paramedic is holding the kid's arms up so we can see them, over","Lockbox-6","Wait one","Lockbox-6","Lockbox-1-6, battalion says negative - nothing crosses, pass burn dressings and saline across the barrier, over","Lockbox-1-6","Roger - Sir, the paramedic wants to know whose name he should give when people ask him who said no, over","Lockbox-6","Tell him it was me - Lockbox-6, out"}},
{"r2_d2_bridge_strollers","military",2,3,6,20,1,{"Lockbox-1-6","Lockbox-6, TCP 1, about two hundred civilians on foot at the south end of the bridge, moving up the deck toward the first barrier, over","Lockbox-6","Loudspeaker from the first light pole, four hundred meters - tell them the bridge is closed, again at the second pole, over","Lockbox-1-6","We've been telling them since the first pole, they keep walking, the front of the crowd is families pushing strollers stacked with suitcases, over","Lockbox-6","Anyone in the crowd sick, over?","Lockbox-1-6","Can't tell at this range, some of them are limping - it's a long bridge in this heat, over","Lockbox-6","Hold at the barrier, nobody fires unless ordered by me, personally - acknowledge, over","Lockbox-1-6","Acknowledged - Sir, a man at the front is holding up a bedsheet - somebody wrote NOT SICK on it in shoe polish, over","Lockbox-6","Keep the loudspeaker going, say it slow, I'm on my way to you - Lockbox-6, out"}},
{"r2_d2_no_illum_insulin","military",2,4,21,4,1,{"Crowbar-2-6","Crowbar-6, Crowbar-2-6, movement in the tree line east of TCP 5, no count - request illumination, over","Crowbar-6","Negative illumination, I say again, negative - use your night sights, over","Crowbar-2-6","Sir, we fired illum over this same field last night and had three times the movement by midnight, over","Crowbar-6","That's why it's negative, light brings them - noise brings them - shut down your generator, over","Crowbar-2-6","The generator runs the floodlight and the little refrigerator with the insulin in it, over","Crowbar-6","Whose insulin, over?","Crowbar-2-6","Civilian woman in the holding tent, diabetic - it's hers, she brought it from home in a lunchbox, over","Crowbar-6","Pack the insulin in a cooler with ice off the ration truck, then kill the generator - Crowbar-6, out"}},
{"r2_d2_grain_bin_rows","military",2,4,7,19,1,{"Hatchet Overwatch","Hatchet-6, Overwatch, from the top of the co-op grain bin I have Category Threes crossing the soybean field toward TCP 3, over","Hatchet-6","Send numbers, over","Hatchet Overwatch","I counted forty-one and lost the count behind the hedgerow - I'm counting rows instead, six rows, loose, over","Hatchet-6","Distance, over?","Hatchet Overwatch","Eight hundred meters, closing at a walk, they don't go around the irrigation pipe, they go over it and fall and get up, over","Hatchet-6","Roger, do not engage until they reach the fence line, every round you fire tells the next field where we are, over","Hatchet Overwatch","Understood - request water, it's about a hundred and ten degrees on this metal roof, over","Hatchet-6","Water comes up with your relief at 1600 - keep counting rows - Hatchet-6, out"}},
{"r2_d2_buses_at_gate","military",2,3,9,18,1,{"Anvil-1-6","Anvil-6, Anvil-1-6, six school buses from Muldraugh stopped at the Fort Knox gate - a deputy says they're evacuees ordered to the post gym, over","Anvil-6","Ordered by who, over?","Anvil-1-6","Deputy says the county judge-executive, he has it written on the back of a church bulletin, over","Anvil-6","The post is closed to evacuees, there is no gym - turn them back to Muldraugh, over","Anvil-1-6","Sir, the drivers say they won't drive back, they say the town's gone, there are children on the buses, over","Anvil-6","How many children, over?","Anvil-1-6","They don't know, they loaded whoever was standing in front of the elementary school - the deputy is walking the aisles counting heads now, over","Anvil-6","Wait one","Anvil-6","Anvil-1-6, hold the buses on the shoulder under guard, nobody gets off - I'm taking this to Warden-6 in person, over","Anvil-1-6","Roger, holding, it's ninety-four degrees, sir - the windows on those buses only go halfway down, over","Anvil-6","I know it - Anvil-6, out"}},
{"r2_d2_lace_tcp","military",2,2,6,12,1,{"Warden Main","Hatchet-6, Warden Main, send LACE for TCP 2 and TCP 3, over","Hatchet-6","Hatchet-6 - TCP 2 - liquids amber - ammunition amber, casualties, one wounded, one Category Two - equipment green, over","Warden Main","Roger TCP 2, confirm the Category Two is one of ours, over","Hatchet-6","Affirmative, private first class, bitten on the calf pulling a man off the wire - Isolated in the back of a five-ton with the tailgate chained, over","Warden Main","Roger, send TCP 3, over","Hatchet-6","TCP 3 - liquids red - ammunition amber - casualties none, equipment amber, two trucks down for fuel - need water before 1500, over","Warden Main","Your water is on the Packhorse-5 convoy, it should be with you by noon, over","Hatchet-6","Packhorse-5 was supposed to be with us yesterday, over","Warden Main","Roger, I'm aware of that - Warden Main, out"}},
{"r2_d2_packhorse_overdue","military",2,3,12,23,2,{"Warden Main","Packhorse-5, Warden Main, radio check, over","Warden Main","Packhorse-5, Packhorse-5, this is Warden Main - how copy, over?","Hatchet-6","Warden Main, Hatchet-6, nothing from Packhorse-5 at TCP 2 or TCP 3, no convoy has passed us, over","Warden Main","Roger - Anvil-6, did Packhorse-5 report through Muldraugh, over?","Anvil-6","Anvil-6, last I heard from them was their call at the Muldraugh overpass, yesterday at 1530 - nine vehicles, all moving, over","Warden Main","Does any station have contact with Packhorse-5 after 1530 yesterday, over?","Crowbar-6","Crowbar-6, negative","Thoroughbred 2-6","Thoroughbred 2-6, negative, we heard trucks gearing down on the county road around dark - could have been anybody's trucks, over","Warden Main","Roger, all stations, Packhorse-5 is overdue, report any sighting of nine Army trucks - Warden Main, out"}},
{"r2_d2_sandlot_dugout","military",2,4,6,11,1,{"Sandlot","Warden Main, Sandlot - morning count - Category One, three hundred eighty-seven - Category Two, nine, over","Warden Main","Roger, three eight seven and nine, you had fourteen Twos yesterday, over","Sandlot","Affirmative, five of them moved to the other list overnight, over","Warden Main","Understood - are the Twos separated from the Ones, over?","Sandlot","They're in the dugout with the gate padlocked, the Ones can see them from the bleachers - there is nowhere else to put them, over","Warden Main","Hang tarps on the fence, over","Sandlot","Already done, the families carried their lawn chairs up to the tarps so they can talk through them, over","Warden Main","Keep them three meters off that fence - Sandlot, how are you on food, over?","Sandlot","Two days of rations if nobody goes back for seconds - nobody's going back for seconds, over","Warden Main","Roger - Warden Main, out"}},
{"r2_d2_mercy_turns_north","military",2,4,8,20,1,{"Warden Air","Civilian helicopter southbound over the river at one thousand feet, this is Army Warden Air on guard - you are entering restricted airspace - turn north immediately, over","Mercy 3","Army, Mercy 3, a hospital helicopter out of Louisville, doctor and nurse aboard - we've been asked to pick up a patient at a farm near Rosewood, over","Warden Air","Mercy 3, negative, no aircraft lands inside the quarantine - turn north now, over","Mercy 3","Army, the patient is the doctor's own father, he's standing out in his yard next to a white sheet he laid down for us, over","Warden Air","Mercy 3, I understand, if you land, you will not be permitted to leave - I say again, you will not be permitted to leave, over","Mercy 3","Understood - stand by","Mercy 3","Army, Mercy 3, turning north, the doctor asks if anyone can drive by the farm on Old Rosewood Road and tell his dad we came, over","Warden Air","Mercy 3, I can't promise that, I wrote it down - Warden Air, out"}},
{"r2_d2_marty_word_list","military",2,3,19,23,1,{"Marty","It's Marty again, from March Ridge, I've been writing down the words they use on the scanner, so I can tell you what they mean - I'm not sure of all of them","Marty","Category One is a person who isn't sick - Category Two is somebody who's been bitten - Category Three is what a Two turns into, they say it like it's a grade of feed","Marty","TCP means traffic control point, that's a roadblock, when they say a vehicle was turned back, I believe it means exactly that","Marty","There was a word this afternoon - minimize, as best I can tell, it means they want to say less, because people like me are listening","Marty","I understand why they'd want that, I'm going to keep listening anyway, somebody in this county ought to know what's being decided about it"}},
{"r2_mis_said_repeat","military_mistake",2,6,0,23,1,{"Anvil-1-6","Thunder-2, Anvil-1-6, rounds on target - Category Threes dispersed on the Muldraugh bypass, good effect, over","Thunder-2","Anvil-1-6, Thunder-2, roger good effect - say if end of mission, over","Anvil-1-6 RTO","Thunder-2, sorry, it's loud here - repeat, over","Thunder-2","Roger, repeat - shot, over","Anvil-1-6","Check fire, check fire, check fire! Who said repeat? Who said repeat on my handset?","Thunder-2","Check fire, roger, rounds already in the air - splash in five, over","Anvil-1-6","Everybody down - Doyle, give me that handset, the word is say again - it is always say again","Anvil-1-6","Thunder-2, Anvil-1-6, rounds impacted the same empty field, no friendly casualties - one very quiet private, end of mission, over","Thunder-2","End of mission, roger - tell the private we've all done it once - thunder-2, out"}},
{"r2_mis_blue_dumpsters","military_mistake",2,5,0,23,1,{"Hatchet-2-2","Hatchet-2-6, Hatchet-2-2, we're set up behind the First Baptist in Muldraugh, by the back door with the dumpsters, over","Hatchet-2-7","Hatchet-2-2, Hatchet-2-7, do not send locations in the clear - use the reference points, over","Hatchet-2-2","Sergeant, which reference point is the church, over?","Hatchet-2-7","Checkpoint Oscar, over","Hatchet-2-2","Roger, we're behind checkpoint Oscar, by its dumpsters, the blue ones, over","Hatchet-2-7","Stop describing the dumpsters, everybody with a scanner in this county knows where the blue dumpsters are, over","Hatchet-2-2","Roger, no dumpsters, standing by at checkpoint Oscar, which is a church, over","Hatchet-2-7","Hatchet-2-2, I'm walking over there now, and you and I are going to talk - out"}},
{"r2_mis_what_is_twenty","military_mistake",2,6,0,23,1,{"Unit 9","Army unit on the sheriff's channel, what's your twenty?","Striker-2-2","Uh, I'm twenty-three, ma'am, over","Unit 9","Your location, son, twenty means where are you","Striker-2-2","Roger, sorry, we're at the grain elevator on the Ekron road, over","Unit 9","10-4, I'm five minutes out with a prisoner who's a Category, whatever y'all call it - can I bring him to you?","Striker-2-2","Ma'am, stand by - Sergeant says negative, do not bring him, over","Unit 9","Then what am I supposed to do with him?","Striker-2-7","Unit 9, Striker-2-7 - keep him in the back seat with the windows up and the cage shut - we're getting off your channel now, ma'am - out"}},
{"r2_mis_grease_pencil_six","military_mistake",2,5,0,23,1,{"Hatchet-3-6","Warden Main, Hatchet-3-6, set at TCP 4, over","Crowbar-1-6","Warden Main, Crowbar-1-6, also set at TCP 4 - I'm looking at Hatchet's trucks from here, over","Warden Main","Stand by - Hatchet-3-6, you were assigned TCP 6, over","Hatchet-3-6","Negative, my order says 4, the number on the overlay looks like a 4, over","Warden Main","That overlay was drawn with a grease pencil in a moving truck - it's a 6, over","Crowbar-1-6","Then who's been sitting at TCP 6 since last night, over?","Warden Main","Stand by","Warden Main","Hatchet-3-6, move to TCP 6 immediately and report what you find, over","Hatchet-3-6","Moving - Warden Main, if nobody's been at 6, anything that wanted out of this county has had a full night's head start, over","Warden Main","Understood - move - Warden Main, out"}},
{"r2_mis_breaker_nineteen","military_mistake",2,7,7,21,1,{"Sergeant Tanner","Breaker, breaker, this is Sergeant First Class Tanner, United States Army, on a CB out of a truck cab - anybody on this channel, over","Buckshot","Come on back, Army, this is Buckshot, eastbound on Highway 60, sitting still for two days now - you lost?","Sergeant Tanner","Negative, not lost, our radios are down, I need somebody to carry a message to the checkpoint on the Brandenburg road, over","Buckshot","Army, I can't get to the Brandenburg road, y'all put a checkpoint in front of it","Sergeant Tanner","Understood - is anyone on this channel close to that checkpoint, over?","Sweet Tea","This is Sweet Tea, I'm two cars back from the barrier - what do you want said, Army?","Sergeant Tanner","Tell the soldiers at the barrier that Tanner's squad is alive at the Ekron grain elevator and needs water, over","Sweet Tea","I'll holler it at them, they haven't let me talk to them in two days, but I'll holler","Buckshot","And Army? You don't say over on nineteen, you say come back - keep the shiny side up"}},
{"r2_mis_road_department_hum","military_mistake",2,6,0,23,1,{"Lockbox-6","All units, this is Lockbox-6, whoever keeps humming on this net will be found, and will be sorry, over","Road Department 3","Lockbox-6, this is Knox County Road Department, truck 3, you're on our frequency, Captain, nobody here is playing around","Lockbox-6","Say again, this is the road department, over?","Road Department 3","Yes sir, potholes and snowplows - we're down to one truck and the dispatcher, she hums when she's scared","Lockbox-1-2","Sir, Lockbox-1-2, you've got the wrong preset on the vehicle radio, it's the second knob, the one with the tape on it, over","Lockbox-6","Road Department, my apologies to your dispatcher - tell her she can hum all she wants - Lockbox-6, out","Road Dispatch","Thank you, Captain, I'll try and keep it in tune"}},
{"r2_mis_goat_not_rover","military_mistake",2,6,0,23,1,{"Warden Main","All stations, reminder, a Category Three at your perimeter is reported as Rover - I spell, Romeo Oscar Victor Echo Romeo, over","Hatchet-2-4","Hatchet-2-6, Hatchet-2-4 - Rover at the east wire, over","Hatchet-2-6","Roger Rover - how many, over?","Hatchet-2-4","One, it's small and its tail is wagging, over","Hatchet-2-6","Say again, wagging, over?","Hatchet-2-4","Sir, this one's a goat, somebody's goat with a bell on its neck, it's eating a sandbag, over","Hatchet-2-6","Hatchet-2-4, a goat is not a Rover, do not report livestock as Rover, over","Hatchet-2-4","Roger - what do I call a goat, over?","Hatchet-2-6","Call it a goat - Hatchet-2-6, out"}},
{"r2_mis_read_back_correct","military_mistake",2,6,0,23,2,{"Warden Main","Striker-2-6, Warden Main - move your platoon to reinforce the holding area in Rosewood, over","Striker-2-6","Striker-2-6 reads back - move to reinforce the holding area in Riverside, over","Warden Main","Read back correct, move out, over","Striker-2-6","Warden Main, Striker-2-6, set in Riverside, there's no holding area here - there's nobody here, over","Warden Main","Striker-2-6, say your location, over","Striker-2-6","Riverside, per your order, over","Warden Main","My order was Rosewood, I spell, Romeo Oscar Sierra Echo Whiskey Oscar Oscar Delta, over","Striker-2-6","My read back was Riverside, and you said read back correct, over","Warden Main","Understood, the mistake is mine - Rosewood called for help ninety minutes ago - move now, over","Striker-2-6","Moving, it's forty minutes from here - Striker-2-6, out"}},
{"r2_mis_courier_callsign","military_mistake",2,6,0,3,1,{"Warden Main","Anvil-6, Warden Main, over","Anvil-6","Warden Main, Anvil-6, go ahead, over","Crowbar-6","Warden Main, this is Viper-6, formerly Crowbar-6, callsigns changed at midnight, over","Warden Main","Stand by, all stations, check your signal instructions, callsigns changed at 0001 - Anvil is now Saber, over","Anvil-6","Warden Main, Anvil-6, nobody brought us the new page - we're still Anvil, over","Warden Main","Understood - who else did not receive the new page, over?","Hatchet-6","Hatchet-6, or whatever I am tonight, didn't get it, over","Warden Main","Roger, all stations revert to yesterday's callsigns until further notice - the courier carrying the new pages hasn't reported in, over","Crowbar-6","Roger, Crowbar again - did the courier have a callsign, over?","Warden Main","He did, nobody's sure which one - Warden Main, out"}},
{"r2_mis_say_it_mull_draw","military_mistake",2,4,7,20,1,{"Striker-2-4","Striker-2-6, Striker-2-4, we're approaching Mull-drag, over","Striker-2-6","Say again the town, over","Striker-2-4","Mul - Mul-drog, sir, it's spelled with a U-G-H on the end, over","Thoroughbred 2-6","Army, Thoroughbred 2-6 - it's Mull-draw, like drawing water from a well, folks there will set you straight if you say it wrong, over","Striker-2-4","Roger, Mull-draw, thanks, Guard, over","Thoroughbred 2-6","And Army, if there's anybody left in shape to correct you, you let them, over"}},
{"r2_mis_berm_wrong_side","military_mistake",2,4,7,20,1,{"Sapper-6","Warden Main, Sapper-6 - Echo Creek berm is complete, over","Warden Main","Roger, send your location, over","Sapper-6","Stand by","Sapper-6","Warden Main, Sapper-6 - be advised, my dozer and two of my soldiers are on the outside of the berm - the rest of us are on the inside, over","Warden Main","Say again, outside, over?","Sapper-6","The operator pushed the last blade of fill from the wrong end - it's a very good berm, it's twelve feet high from both directions, over","Warden Main","Can they climb it, over?","Sapper-6","Affirmative, but per the order, anyone who crosses the line doesn't come back in - request a ruling on my own dozer operator, over","Warden Main","Stand by for a ruling","Warden Main","Sapper-6, Warden-6 rules the berm was not complete until the operator was on the correct side of it - get him over - Warden Main, out"}},
{"r3_so_d2_first_words","sign_on",2,2,5,8,6,{"Marty","Good morning, this is, uh - hold on, let me start that over","Marty","Good morning, my name is Martin Colburn - I own Colburn Feed and Seed on the main road in March Ridge","Marty","You're hearing this on ninety-nine point six, FM, I sell feed - I have never in my life talked into a microphone on purpose","Marty","Today is Sunday, July the eleventh, the television in my store has shown nothing but static since yesterday afternoon","Marty","I have a transmitter, a generator, and a police scanner - I intend to read you what I hear and tell you plainly when I don't know something","Marty","If you can hear me, stay where you are for now - I'll come back on at the top of the hour"}},
{"r3_sf_d2_wind_up_clock","sign_off",2,2,22,2,5,{"Marty","That's everything I have for tonight","Marty","I'm turning the transmitter off to save fuel, I'll turn it back on at six in the morning - I've set an alarm clock, the wind-up kind","Marty","If you're alone tonight, you're not the only one, I'm alone too, the store cat doesn't count, she's made that clear","Marty","This is Marty Colburn, ninety-nine point six - good night"}},
{"r3_host_d2_lloyd_rig","host",2,4,0,23,3,{"Marty","Some of you are wondering how a feed store got a radio station","Marty","This transmitter belonged to Lloyd Tipton - Lloyd called the high school football games on Friday nights for fifteen years, off a card table in the press box","Marty","He kept it in my back room between seasons, because his wife wanted it out of the house","Marty","His labels are still on the knobs, in his handwriting - one of them just says 'DON'T.' I haven't touched that one","Marty","Lloyd isn't in a position to use it now, I think he'd rather it was talking than sitting"}},
{"r3_ins_d2_bathtub","instruction",2,4,5,12,4,{"Marty","If your tap still runs, even a trickle, fill the bathtub now - then pots, pitchers, any jar you've got","Marty","The water tower works by gravity, when the pumps quit Saturday, the tower kept on giving - it won't do that forever","Marty","Lay a towel or a sheet of cardboard over the tub so the dust stays out - that tub is your drinking water now, it is not a bath","Marty","Drink out of the jars first, since they're covered better - save the tub for last"}},
{"r3_ins_d2_chainsaw","instruction",2,5,0,23,3,{"Marty","I'm going to say something plain, they come to noise","Marty","A man told me he started his chainsaw on Sunday to get a limb off his carport, and inside of ten minutes he had four of them standing in his yard","Marty","No mowers, no chainsaws - don't bang on the pipes - don't let the dog bark if you can help it, and I know you can't always help it","Marty","If you have to hammer something, fold a quilt under it - it's slower, you'll be around to finish"}},
{"r3_ins_d2_the_fever","instruction",2,7,5,20,1,{"Marty","People have asked what to do when somebody in the house has been bitten - I'm not a doctor, I'll tell you only what I've heard from people who saw it","Marty","The ones I've heard about ran a fever inside of a day - then they got very sleepy, then they didn't wake up the same way they lay down","Marty","I'm not going to tell you what to do about that - I'll tell you not to sleep in the same room with them once the fever comes","Marty","And put a lock between you, on your side of the door - I'm sorry, I truly am"}},
{"r3_ins_d2_eat_order","instruction",2,4,5,12,1,{"Marty","Here's the order to eat things in if your power's out - the refrigerator first, then the freezer, then the cans - cans always last","Marty","A full freezer that stays shut keeps cold about two days - half full, about one, so stop opening it to look","Marty","Meat that smells wrong is wrong - don't just cook it hotter and hope, bag it and carry it well away from the house, because it'll draw dogs, maybe worse","Marty","If a can is swelled up, or it spits at you when you open it, throw it out - I don't care how hungry you are"}},
{"r3_ins_d2_heat_house","instruction",2,7,5,11,1,{"Marty","It'll be over ninety again today, and most of you have your houses shut up tight with no fans running","Marty","Open the upstairs windows, where nothing can reach, and keep the downstairs shut - heat goes up and out, it's the one thing in this county still doing what it's supposed to","Marty","Wet a washcloth and lay it on the back of your neck - put your wrists in cool water a few minutes at a time","Marty","If somebody quits sweating, gets confused, and their skin goes hot and dry, that's heat stroke - get them cool fast, any way you can","Marty","Old folks and babies first, they won't tell you they're too hot, you have to go and check"}},
{"r3_wx_d2_knee","weather",2,4,5,10,1,{"Marty","Weather, I'll do it the way I did it for the farmers who came in every morning, which is read you my barometer, my rain gauge, and my knee","Marty","Barometer on the wall is steady, rain gauge is dry - knee's fine, that adds up to hot and sticky with no relief in it","Marty","Low nineties this afternoon, it might build a storm toward evening, the way July does","Marty","If it storms, that's your time to move around outside if you have to - thunder covers a lot of noise","Marty","That's the weather, my knee's been right more often than the man on Channel 11, and it's still working, which is more than I can say for him"}},
{"r3_mb_d2_needle","music_bridge",2,3,0,23,1,{"Marty","I'm going to stop a minute and make sure this thing is still going out - if you can hear me, you don't need to do a thing","Marty","Testing, ninety-nine point six - testing, one, two, three","Marty","The needle's moving - Lloyd wrote 'GOOD' on a strip of tape right where it's pointing, so I'll take his word for it"}},
}
